using ModelContextProtocol.Server;
using System.Text.Json;

[McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
    Description = "Returns the current application configuration data")]
public class ConfigResource
{
    public static readonly Dictionary<string, object> Settings = new()
    {
        ["environment"] = "production",
        ["version"] = "1.0.0",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [ResourceMethod]
    public string GetSettings()
    {
        return JsonSerializer.Serialize(Settings, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool(Name = "get_config_value"), Description("Gets a specific configuration value by key")]
    public static string GetConfigValue(string key)
    {
        if (ConfigResource.Settings.TryGetValue(key, out var value))
        {
            return System.Text.Json.JsonSerializer.Serialize(value);
        }
        return $"Key '{key}' not found in configuration.";
    }

    [McpServerTool(Name = "list_config_keys"), Description("Lists all available configuration keys")]
    public static string ListConfigKeys()
    {
        return string.Join(", ", ConfigResource.Settings.Keys);
    }
}

